import RNA, random, sys

target = ".....((((.((((.....((((...)))).))))...(((..((((((...)))...)))((((((...)))...))).)))...(((...(((....))).))).))))....."
n = len(target)

# Build pair map
pairs_map = {}
stack = []
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs_map[i] = j
        pairs_map[j] = i

# Identify stems (ordered lists of paired bases)
all_paired = sorted([(i,j) for i,j in pairs_map.items() if i < j])

# Group into stems
used = set()
stems = []
for (i,j) in all_paired:
    if i in used or j in used:
        continue
    stem = [(i,j)]
    used.add(i); used.add(j)
    ii, jj = i+1, j-1
    while (ii, jj) in set((a,b) for (a,b) in all_paired):
        stem.append((ii, jj))
        used.add(ii); used.add(jj)
        ii += 1; jj -= 1
    stems.append(stem)

print(f"Found {len(stems)} stems:")
for si, stem in enumerate(stems):
    print(f"  Stem {si}: {stem}")

unpaired = [i for i in range(n) if target[i] == '.']

random.seed(42)

def fold_seq(seq):
    md = RNA.md()
    md.dangles = 2
    fc = RNA.fold_compound(seq, md)
    struct, mfe = fc.mfe()
    return struct, mfe

def bp_dist(s1, s2):
    def get_set(s):
        ps = set()
        stk = []
        for i, c in enumerate(s):
            if c == '(':
                stk.append(i)
            elif c == ')':
                j = stk.pop()
                ps.add((min(i,j), max(i,j)))
        return ps
    return len(get_set(s1).symmetric_difference(get_set(s2)))

best_seq = None
best_dist = 999

for trial in range(1000):
    seq = ['A'] * n

    for stem in stems:
        for idx, (pi, pj) in enumerate(stem):
            r = random.random()
            if idx == 0:  # closing pair
                if r < 0.8:
                    seq[pi] = 'G'; seq[pj] = 'C'
                else:
                    seq[pi] = 'C'; seq[pj] = 'G'
            else:
                if r < 0.4:
                    seq[pi] = 'G'; seq[pj] = 'C'
                elif r < 0.7:
                    seq[pi] = 'C'; seq[pj] = 'G'
                else:
                    seq[pi] = 'A'; seq[pj] = 'U'

    # Hairpin loops
    seq[23] = random.choice(['G','A']); seq[24] = 'A'; seq[25] = 'A'
    seq[49] = random.choice(['U','C']); seq[50] = 'U'; seq[51] = random.choice(['U','G'])
    seq[67] = random.choice(['G','A','U']); seq[68] = 'A'; seq[69] = 'A'
    seq[95] = 'G'; seq[96] = 'A'; seq[97] = 'A'; seq[98] = 'A'

    # Unpaired linkers: mix A/U to reduce spurious GC interactions
    for p in unpaired:
        if seq[p] == 'A':
            seq[p] = random.choice(['A', 'A', 'A', 'U'])

    s = ''.join(seq)
    struct, mfe = fold_seq(s)
    dist = bp_dist(struct, target)
    if dist < best_dist:
        best_dist = dist
        best_seq = s
        print(f"Trial {trial}: bp_dist={dist}, MFE={mfe:.1f}")
        if dist == 0:
            break

print(f"\nBest: bp_dist={best_dist}")
print(f"Sequence: {best_seq}")
